 @Test void listagensEHistoricoSemNMaisUm(){var stats=em.getEntityManagerFactory().unwrap(org.hibernate.SessionFactory.class).getStatistics();service.emprestar(loan(),key());stats.clear();service.listar(all(),0,100);long one=stats.getPrepareStatementCount();for(int i=0;i<12;i++)service.criar(criacao(null));stats.clear();service.listar(all(),0,100);assertTrue(stats.getPrepareStatementCount()<=one+1);stats.clear();service.historico(ativoId,0,20);assertTrue(stats.getPrepareStatementCount()<=4);}
 boolean run(Callable<?> task,org.springframework.security.core.Authentication auth,CountDownLatch start)throws Exception{SecurityContextHolder.getContext().setAuthentication(auth);try{start.await();task.call();return true;}catch(ConflitoException|org.springframework.dao.DataIntegrityViolationException e){return false;}finally{SecurityContextHolder.clearContext();}}
 void race(Callable<?> one,Callable<?> two)throws Exception{var auth=SecurityContextHolder.getContext().getAuthentication();var start=new CountDownLatch(1);var pool=Executors.newFixedThreadPool(2);try{var a=pool.submit(()->run(one,auth,start));var b=pool.submit(()->run(two,auth,start));start.countDown();assertNotEquals(a.get(30,TimeUnit.SECONDS),b.get(30,TimeUnit.SECONDS));}finally{pool.shutdownNow();}}
