 @ParameterizedTest @EnumSource(value=TipoRegistroAtivo.class,names={"TRANSFERENCIA","RECEBIMENTO","DEVOLUCAO","INSPECAO","BAIXA"}) void rollbackTodosEventosCriticos(TipoRegistroAtivo type){Integer origem=type==TipoRegistroAtivo.DEVOLUCAO?(Integer)service.emprestar(loan(),key()).get("id"):type==TipoRegistroAtivo.RECEBIMENTO?(Integer)service.transferir(transfer(),key()).get("id"):null;var before=service.buscar(ativoId);long events=registros.count(),audits=eventos.count();String k=key();var t=type==TipoRegistroAtivo.TRANSFERENCIA?transfer():null;tx.executeWithoutResult(x->doThrow(new IllegalStateException("falha H2")).when(audit).registrar(eq("ATIVO_"+type),anyString(),anyString(),any(),any(),any()));assertThrows(IllegalStateException.class,()->{switch(type){case TRANSFERENCIA->service.transferir(t,k);case RECEBIMENTO->service.receber(origem,arrival(),k);case DEVOLUCAO->service.devolver(origem,returned(),k);case INSPECAO->service.inspecionar(inspection(ResultadoInspecao.REPROVADO),k);case BAIXA->service.situacao(ativoId,situation(TipoRegistroAtivo.BAIXA),k);default->throw new AssertionError();}});assertEquals(before,service.buscar(ativoId));assertEquals(events,registros.count());assertEquals(audits,eventos.count());assertTrue(registros.findByChaveIdempotencia(k).isEmpty());}
