 @Test void historicosMultiplosNaoMultiplicamAtivoOuDashboard(){long before=((Number)service.resumo().get("emprestimosAbertos")).longValue();for(int j=0;j<3;j++)service.devolver((Integer)service.emprestar(loan(),key()).get("id"),returned(),key());service.emprestar(loan(),key());assertEquals(before+1,((Number)service.resumo().get("emprestimosAbertos")).longValue());assertEquals(1,service.listar(new AtivosService.Filtro((String)service.buscar(ativoId).get("codigoPatrimonial"),null,null,null,null,null,null,null,null,null,null),0,20).getTotalElements());var list=service.listarRegistros(TipoRegistroAtivo.EMPRESTIMO,ativoId,null,null,null,null,true,null,null,null,0,20);assertEquals(1,list.getTotalElements());assertTrue((Boolean)list.getContent().get(0).get("aberto"));assertEquals(7,service.historico(ativoId,0,20).getTotalElements());}
 @Test void todasConsultasMantemNumeroConstanteDeQueries(){var stats=em.getEntityManagerFactory().unwrap(org.hibernate.SessionFactory.class).getStatistics();stats.clear();service.resumo();long dashboardQueries=stats.getPrepareStatementCount();for(int j=0;j<15;j++)service.inspecionar(inspection(ResultadoInspecao.APROVADO),key());for(var tipo:List.of(TipoRegistroAtivo.EMPRESTIMO,TipoRegistroAtivo.TRANSFERENCIA,TipoRegistroAtivo.INSPECAO)){stats.clear();service.listarRegistros(tipo,null,null,null,null,null,null,null,null,null,0,100);assertTrue(stats.getPrepareStatementCount()<=4,"N+1 em "+tipo);}stats.clear();service.historico(ativoId,0,100);assertTrue(stats.getPrepareStatementCount()<=4);stats.clear();service.buscar(ativoId);assertTrue(stats.getPrepareStatementCount()<=2);stats.clear();service.resumo();assertEquals(dashboardQueries,stats.getPrepareStatementCount());}
 @ParameterizedTest @EnumSource(Perfil.class) void matrizHttpTodos18HandlersComPayloadReal(Perfil perfil)throws Exception{
  int loanId=(Integer)service.emprestar(loan(),key()).get("id");int transferAsset=(Integer)service.criar(criacao(null)).get("id");var transfer=transfer();transfer.ativoId=transferAsset;int transferId=(Integer)service.transferir(transfer,key()).get("id");int available=(Integer)service.criar(criacao(null)).get("id");var inspect=inspection(ResultadoInspecao.APROVADO);inspect.ativoId=available;int inspectionId=(Integer)service.inspecionar(inspect,key()).get("id");String code=(String)service.buscar(available).get("codigoPatrimonial");
  identity(perfil);var authentication=SecurityContextHolder.getContext().getAuthentication();for(String path:List.of("/ativos","/ativos/resumo","/ativos/"+ativoId,"/ativos/"+ativoId+"/historico","/emprestimos","/emprestimos/"+loanId,"/transferencias-ativos","/transferencias-ativos/"+transferId,"/inspecoes-ativos","/inspecoes-ativos/"+inspectionId))mvc.perform(get(path).with(authentication(authentication))).andExpect(status().isOk());
  var inputs=List.of(new String[]{"POST","/ativos","{\"cadastro\":{\"nome\":\"Ativo HTTP H2\"},\"almoxarifadoId\":"+warehouse+",\"condicao\":\"BOM\"}","ATIVO_GERENCIAR"},new String[]{"PUT","/ativos/"+available,"{\"codigoPatrimonial\":\""+code+"\",\"nome\":\"Ativo editado HTTP\"}","ATIVO_GERENCIAR"},new String[]{"POST","/emprestimos","{\"ativoId\":"+available+",\"entreguePorId\":"+person+",\"funcionarioId\":"+person+",\"condicao\":\"BOM\"}","EMPRESTIMO_GERENCIAR"},new String[]{"POST","/emprestimos/"+loanId+"/devolucao","{\"devolvidoPorId\":"+person+",\"recebidoPorId\":"+person+",\"condicao\":\"BOM\"}","EMPRESTIMO_GERENCIAR"},new String[]{"POST","/transferencias-ativos","{\"ativoId\":"+ativoId+",\"entreguePorId\":"+person+",\"almoxarifadoId\":"+transfer.almoxarifadoId+",\"condicao\":\"BOM\"}","TRANSFERENCIA_ATIVO_GERENCIAR"},new String[]{"POST","/transferencias-ativos/"+transferId+"/recebimento","{\"recebidoPorId\":"+person+",\"condicao\":\"BOM\"}","TRANSFERENCIA_ATIVO_GERENCIAR"},new String[]{"POST","/inspecoes-ativos","{\"ativoId\":"+available+",\"inspetorId\":"+person+",\"condicao\":\"BOM\",\"resultado\":\"APROVADO\"}","INSPECAO_ATIVO_GERENCIAR"},new String[]{"PUT","/ativos/"+transferAsset+"/situacao","{\"acao\":\"INATIVACAO\",\"responsavelId\":"+person+",\"motivo\":\"Registro HTTP H2\"}","ATIVO_GERENCIAR"});
  for(var input:inputs){var request=input[0].equals("POST")?post(input[1]):put(input[1]);int expected=perfil.permissoes().contains(Permissao.valueOf(input[3]))?200:403;mvc.perform(request.with(authentication(authentication)).with(csrf()).header("Idempotency-Key",key()).contentType(MediaType.APPLICATION_JSON).content(input[2])).andExpect(status().is(expected));}
 }
